// Updated Merge Chunks — also collect words array
const items = $input.all();
const allSegments = [];
const allWords = [];

for (const item of items) {
  const offset   = item.json.offsetSeconds || 0;
  const segments = item.json.segments || [];
  const words    = item.json.words    || [];

  for (const seg of segments) {
    if (seg.start === null || seg.end === null) continue;
    allSegments.push({ start: seg.start + offset, end: seg.end + offset, text: seg.text.trim() });
  }

  for (const w of words) {
    allWords.push({ start: w.start + offset, end: w.end + offset, word: w.word });
  }
}

allSegments.sort((a, b) => a.start - b.start);
allWords.sort((a, b) => a.start - b.start);

// Deduplicate segments
const cleaned = [];
for (const seg of allSegments) {
  if (!cleaned.length) { cleaned.push(seg); continue; }
  const prev = cleaned[cleaned.length - 1];
  if (seg.start < prev.end - 0.1) continue;
  if (seg.start < seg.end) cleaned.push(seg);
}

return [{ json: { segments: cleaned, words: allWords } }];

const outputPath = $json.body.outputPath;


if (!outputPath) throw new Error('No outputPath received');

return {
  json: {
    fileId: outputPath.split('/').pop(),
    outputPath: outputPath
  }
};

// Get file path from the extract drive file id node
const outputPath = $('get file path from webhook').item.json.outputPath;

return {
  json: {
    downloadedFile: outputPath
  }
};

const downloadedFile = $('format file path').first().json.downloadedFile;

// Get stderr from FFmpeg which contains duration info
const stderr = $('FFmpeg split video into chunks').first().json.stderr;

// Extract duration from ffmpeg output
const durationMatch = stderr.match(/Duration: (\d+):(\d+):(\d+)/);
const totalSeconds = durationMatch 
  ? parseInt(durationMatch[1]) * 3600 + parseInt(durationMatch[2]) * 60 + parseInt(durationMatch[3])
  : 3600; // default 1 hour if not found

const chunkDuration = 600; // 10 minutes
const numChunks = Math.ceil(totalSeconds / chunkDuration);

const chunks = [];
for (let i = 0; i < numChunks; i++) {
  chunks.push({
    json: {
      filePath: `/root/.n8n-files/chunk_${String(i).padStart(3, '0')}.mp3`,
      chunkIndex: i,
      offsetSeconds: i * chunkDuration
    }
  });
}

return chunks;

// Attach the offset from the input item to the Groq response
const items = $input.all();
return items.map((item, index) => ({
  json: {
    ...item.json,
    offsetSeconds: index * 600
  }
}));

const items = $input.all();
const allSegments = [];
const allWords = [];

for (const item of items) {
  const response = item.json;
  const segments = response.segments || [];
  const words = response.words || [];
  const offset = response.offsetSeconds || 0;

  if (segments.length > 0 && segments[0].start !== null) {
    for (const seg of segments) {
      allSegments.push({
        start: seg.start + offset,
        end: seg.end + offset,
        text: seg.text.trim()
      });
    }
  } else {
    const chunkSize = 8;
    for (let i = 0; i < words.length; i += chunkSize) {
      const chunk = words.slice(i, i + chunkSize);
      if (!chunk.length) continue;
      allSegments.push({
        start: chunk[0].start + offset,
        end: chunk[chunk.length - 1].end + offset,
        text: chunk.map(w => w.word).join(' ')
      });
    }
  }

  for (const w of words) {
    allWords.push({
      start: w.start + offset,
      end: w.end + offset,
      word: w.word
    });
  }
}

allSegments.sort((a, b) => a.start - b.start);
allWords.sort((a, b) => a.start - b.start);

return [{ json: { segments: allSegments, words: allWords } }];

const MAX_CLIPS = $('Webhook').first().json.body.clipCount || 3;
const results = [];

for (const item of $input.all()) {
  try {
    let output = item.json.output;
    if (typeof output === 'string') {
      output = JSON.parse(output.replace(/```json|```/g, '').trim());
    }
    if (Array.isArray(output)) {
      results.push(...output);
    }
  } catch (e) {
    console.log('Error:', e);
  }
}

function fixTimestamp(ts) {
  if (!ts || typeof ts !== 'string') return null;
  ts = ts.trim().replace(',', '.');
  const parts = ts.split(':');
  let h = 0, m = 0, s = 0;
  if (parts.length === 2) {
    m = parseInt(parts[0]) || 0;
    s = parseFloat(parts[1]) || 0;
  } else if (parts.length === 3) {
    h = parseInt(parts[0]) || 0;
    m = parseInt(parts[1]) || 0;
    s = parseFloat(parts[2]) || 0;
  } else return null;
  if (isNaN(h) || isNaN(m) || isNaN(s)) return null;
  m += Math.floor(s / 60); s = s % 60;
  h += Math.floor(m / 60); m = m % 60;
  return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${s.toFixed(3).padStart(6,'0')}`;
}

results.sort((a, b) => b.score - a.score);

const topClips = results
  .slice(0, MAX_CLIPS)
  .map((c, i) => ({
    ...c,
    index: i,
    start: fixTimestamp(c.start),
    end: fixTimestamp(c.end)
  }))
  .filter(c => c.start !== null && c.end !== null);

return topClips.map(c => ({ json: c }));

