  json: {
    status: item.json.status,
    id: item.json.id,
    index: item.json.index,
    utterances: item.json.utterances || []
  }
}));

const utterances = $('Extract speaker segments1').first().json.utterances;
const speakerLabel = $input.first().json.output.speakerLabel;
const targetName = $('Extract speaker segments1').first().json.targetName;

const targetUtterances = utterances.filter(u => u.speaker === speakerLabel);

const clips = [];
let currentClip = null;
const GAP_THRESHOLD = 3000;
const MIN_DURATION = 20000;
const MAX_DURATION = 150000;

for (const u of targetUtterances) {
  if (!currentClip) {
    currentClip = { start: u.start, end: u.end, text: u.text };
    continue;
  }
  const gap = u.start - currentClip.end;
  const duration = u.end - currentClip.start;
  if (gap > GAP_THRESHOLD || duration > MAX_DURATION) {
    if (currentClip.end - currentClip.start >= MIN_DURATION) clips.push(currentClip);
    currentClip = { start: u.start, end: u.end, text: u.text };
  } else {
    currentClip.end = u.end;
    currentClip.text += ' ' + u.text;
  }
}

if (currentClip && currentClip.end - currentClip.start >= MIN_DURATION) clips.push(currentClip);

const clipCount = $('Webhook').first().json.body.clipCount || 3;

function msToTimestamp(ms) {
  const h = Math.floor(ms / 3600000);
  const m = Math.floor((ms % 3600000) / 60000);
  const s = ((ms % 60000) / 1000).toFixed(3);
  return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(6,'0')}`;
}

return clips
  .sort((a, b) => (b.end - b.start) - (a.end - a.start))
  .slice(0, clipCount)
  .map((c, i) => ({
    json: {
      index: i,
      start: msToTimestamp(c.start),
      end: msToTimestamp(c.end),
      hook: c.text.substring(0, 100),
      score: 0.95
    }
  }));

const stderr = $input.first().json.stderr
const stdout = $input.first().json.stdout

// Check ffmpeg actually completed
if (!stdout.includes('done')) {
  throw new Error('FFmpeg failed: ' + stderr);
}

return [{
  json: {
    audioPath: '/root/.n8n-files/full_audio.mp3'
  }
}];

